"""Character-class baseline for layers.15.mlp.down_proj component 5122.

The component's activation is diffuse: mean -0.018, standard deviation 0.32, and it is
not set by the current token's identity, the previous token, the position in the document,
or whether the token repeats earlier text. The only mild pattern is by the kind of token
written: whitespace and punctuation sit a little below the mean, CJK characters a little
above it, and the first token of each document is about zero. This program predicts each
of those class means. It explains almost none of the variance.
"""

import unicodedata

READS = ()

CLASS_MEAN = {"space": -0.046, "punct": -0.028, "digit": -0.025, "alpha": -0.017, "cjk": -0.008, "other": -0.02}


def token_class(text):
    s = text.strip()
    if not s:
        return "space"
    if all(unicodedata.category(c).startswith(("P", "S")) for c in s):
        return "punct"
    if all(c.isdigit() for c in s):
        return "digit"
    if any("一" <= c <= "鿿" for c in s):
        return "cjk"
    if s.isalpha():
        return "alpha"
    return "other"


def step(carry, prefix, upstream):
    if prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return carry, 0.0
    return carry, CLASS_MEAN[token_class(prefix.token_strings[-1])]

"""Component L15 down_proj #5138: a negative "list-joining word" detector.

It goes negative on a word that joins alternatives or parallel items inside a sentence:
strongest on " or" and its translations (" oder", " ou", " или", "或", "または", ...),
clearly negative on " either", " nor" and on " and" and its translations (" und", " и",
"和", " &"), weakly negative on " y", " e", " et", and on list commas. Words that introduce
a list of examples (" including", " such", " like") are negative too. Concessive words
(" although", " though", " moreover") are slightly positive. Every other token is near zero.

Tokens are matched as written, leading space included, so " or" counts and "or" inside a
word does not. The program is stateless: it reads only the newest token.
"""

READS: tuple[str, ...] = ()

OR_WORDS = {
    " or", " OR", " oder", " ou", " или", " tai", " lub", " eller", " atau", "或", "或者",
    "或是", "または", "/or", "-or",
}  # fmt: skip
EITHER_NOR = {" either", " nor"}
AND_WORDS = {
    " and", " AND", " und", " и", " og", " och", " &", " و", " ve", " dan", "和", "及", "と",
}  # fmt: skip
WEAK_AND = {" y", " e", " et"}
COMMAS = {",", " ,", "、", "・"}
LIST_WORDS = {" including", "including", " such", " like", " especially", " both"}
CONTRAST = {" although", " though", " moreover", " aunque"}

OR_VALUE = -6.5
EITHER_NOR_VALUE = -3.3
AND_VALUE = -2.2
WEAK_AND_VALUE = -1.0
COMMA_VALUE = -0.6
LIST_WORD_VALUE = -2.0
CONTRAST_VALUE = 0.6
OTHER_VALUE = -0.1


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if token in OR_WORDS:
        return carry, OR_VALUE
    if token in EITHER_NOR:
        return carry, EITHER_NOR_VALUE
    if token in AND_WORDS:
        return carry, AND_VALUE
    if token in WEAK_AND:
        return carry, WEAK_AND_VALUE
    if token in COMMAS:
        return carry, COMMA_VALUE
    if token in LIST_WORDS:
        return carry, LIST_WORD_VALUE
    if token in CONTRAST:
        return carry, CONTRAST_VALUE
    return carry, OTHER_VALUE

"""Prepositions that name an agent, a means, an accompaniment or a cause, written negative.

Component layers.15.mlp.down_proj:5149 is strongly negative on the word that opens an
agent, instrument, accompaniment or reason phrase: "measured BY the sun", "thinned BY
cutting", "WITH a knife", "via email", "SINCE it ends", "BECAUSE of", and their
equivalents in German, French, Spanish, Russian and Chinese ("mit", "avec", "con",
"por", "с", "与"). It is mildly positive on location and scope words ("in", "of",
"for") and near zero on nearly every other token.

The program looks up the current token in word groups and returns the group's typical
activation. It ignores context, so it does not separate "published by" (near zero)
from "measured by" (strongly negative).
"""

READS = ()

AGENT = {" by", " By", " par", " por"}
CAUSE = {" because", " Because", " since", " Since", " debido", " поскольку", " due"}
MEANS = {" with", " With", " mit", " avec", " con", " dengan", " с", " со", " через",
         " 与", " 與", " using", " via", " through", " without", " including",
         " include", " includes", " despite", " unless", " depending", " durch"}
WEAK = {" as", " when", " if", " after", " until"}
LOCATION = {" in", " of", " for", " on", " at", " and", " the", " is", " or"}

# Typical activation for each group (mean over about 1000 eval-like rows).
VALUE = {"agent": -2.7, "cause": -2.3, "means": -2.0, "weak": -0.6, "location": 0.15}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    if tok in AGENT:
        return carry, VALUE["agent"]
    if tok in CAUSE:
        return carry, VALUE["cause"]
    if tok in MEANS:
        return carry, VALUE["means"]
    if tok in WEAK:
        return carry, VALUE["weak"]
    if tok in LOCATION:
        return carry, VALUE["location"]
    return carry, 0.0

"""Layer 15 MLP hidden unit behind down_proj component 5158.

Nearly all of this component is one MLP hidden unit of layer 15 (about 57% of its
variance). Read through the embedding, its output pushes toward words about mystery,
suspicion, reasons and guessing when the activation is negative. The activation is
mostly small and noisy, with occasional large negative spikes. A few plain-language
cues carry a little of its sign and size:

  * the first token of an assistant turn (the token right after "assistant" in the
    chat template) is strongly negative;
  * question marks are negative;
  * words about wondering, explaining, reasons, causes, suspicion, guessing and
    hinting are mildly negative;
  * the reflective interjections "Wait" and "Hmm" are positive.

Everything else predicts 0. Stateless: each position is judged from its own token and
the one or two tokens before it. This is a rough sketch: on training rows it explains
about 1% of the variance.
"""

import re

ASSISTANT_TURN_START = -2.5
QUESTION_MARK = -0.5
SPECULATION_WORD = -0.25
REFLECTIVE_WORD = 0.75

QUESTION_MARKS = {"?", "？"}
REFLECTIVE_WORDS = {"wait", "hmm"}
SPECULATION = re.compile(
    r"(wonder\w*|question\w*|explain\w*|reason\w*|cause\w*|why|suspect\w*|mystery"
    r"|guess\w*|hint\w*|investigat\w*|interpret\w*|alternativ\w*|perhaps|maybe)"
)

READS = ()


def _word(text):
    return text.strip().strip("\"”'").lower()


def step(carry, prefix, upstream):
    strings = prefix.token_strings
    word = _word(strings[-1])
    after_header = len(strings) >= 3 and strings[-3] == "<|im_start|>" and strings[-2].strip() == "assistant"
    if after_header:
        return carry, ASSISTANT_TURN_START
    if word in QUESTION_MARKS:
        return carry, QUESTION_MARK
    if word in REFLECTIVE_WORDS:
        return carry, REFLECTIVE_WORD
    if SPECULATION.fullmatch(word):
        return carry, SPECULATION_WORD
    return carry, 0.0

"""Layer 15 MLP neuron-direction 5161: a punctuation detector.

What it responds to, in plain terms:
- Closing marks. A quotation mark, apostrophe, backtick, or emphasis pair
  (__, **) that comes right after a word fires strongly (about 2.5). The same
  mark after a space or punctuation (an opening quote) stays near 0.
- Possessive markers: English 's and the Chinese/Japanese genitive particles
  的, の, 之 fire moderately (1.5).
- Closing brackets ) ] } and their CJK forms fire (1.4).
- Typographic symbols such as ® ™ ‐ ° $ fire (2.0).
- Dashes fire weakly, and more after a word (1.0 after a word, 0.2 otherwise).
- Other punctuation (commas, periods, colons) and spaces and line breaks sit
  slightly above zero (0.2-0.3).
- Words, numbers and other letters sit near zero (0.0); their small variation
  is not explained by anything simple.

Only the current token and the one before it are read. No state is carried.
"""
from collections.abc import Mapping

READS = ()

# Quote and emphasis marks that close a span; they fire when they follow a word.
QUOTE_MARKS = {'"', "'", "”", "’", "»", "」", "』", "`", "__", "\\_", "**"}
# Possessive markers: English 's and the genitive particles 的, の, 之.
POSSESSIVES = {"'s", "’s", "的", "の", "之"}
CLOSING_BRACKETS = {")", "]", "}", "）", "】", "》"}
SYMBOLS = {"®", "™", "‐", "°", "$", "$$"}
DASHES = {"-", "–", "—"}


def follows_word(prev: str) -> bool:
    """Whether the previous token ends a word or a closing bracket."""
    return prev[-1:].isalnum() or prev[-1:] in ")]}）】》"


def value(tok: str, prev: str) -> float:
    if tok in QUOTE_MARKS:
        return 2.5 if follows_word(prev) else 0.2
    if tok in SYMBOLS:
        return 2.0
    if tok in POSSESSIVES:
        return 1.5
    if tok in CLOSING_BRACKETS:
        return 1.4
    if tok in DASHES:
        return 1.0 if follows_word(prev) else 0.2
    if tok.strip() == "":
        return 0.3
    if any(ch.isalnum() for ch in tok):
        return 0.0
    return 0.2


def step(carry, prefix, upstream: Mapping):
    prev = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    return carry, value(prefix.token_strings[-1], prev)

"""Layer 15 MLP neuron 5166 (a down_proj component), a weak lexical guess.

What it does, in plain terms: the component's activation is mostly the
MLP hidden unit 5166 of layer 15, and that unit is driven by context that
no simple word list captures. This program only encodes the strongest
word-level tendencies seen in the data:

- positive on writer-side words ("we", "us", "our", "I", "me", "мы") and on
  verbs of understanding or finding ("understand", "see", "learn", "know",
  "find", "found", "received"), and on "to" after "forward" or "us";
- negative on reader-side words ("you", "your", "user", "veteran", "вы",
  "вам") and on "to" right after "you";
- a small positive value on a verb that follows "to" or a modal, since
  such verbs carry larger swings.

Everything else predicts 0. It explains well under 1% of the variance.
"""
import wordnet

READS = ()

WRITER = {"we": 0.3, "us": 0.7, "our": 0.0, "i": 0.0, "me": 0.1, "мы": 0.7}
COGNITION = {"understand": 1.2, "see": 0.6, "learn": 0.6, "know": 0.4,
             "find": 0.4, "found": 0.6, "received": 0.4}
READER = {"you": -0.5, "your": 0.0, "user": -0.9, "users": -0.9,
          "veteran": -2.8, "вы": -0.4, "вам": -2.5}
MODAL_OR_TO = {"to", "can", "will", "would", "could", "should", "must", "may", "might"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    prev = prefix.token_strings[-2].strip().lower() if len(prefix.token_strings) > 1 else ""
    if word == "to":
        if prev == "forward" or prev == "us":
            return carry, 1.5
        if prev == "you":
            return carry, -0.8
        return carry, 0.1
    for table in (WRITER, COGNITION, READER):
        if word in table:
            return carry, table[word]
    if prev in MODAL_OR_TO and word.isalpha() and "verb" in wordnet.parts_of_speech(word):
        return carry, 0.2
    return carry, 0.0

"""Word-class rule for the component's activation.

The component writes a vector that pushes the next token toward " and" / " &" (its output
direction promotes those tokens when its activation is negative). Its strongly negative
values come where a coordinating "and" or "&" is about to follow a fixed pair or name
("Centers for Disease Control and Prevention", "Johnson & Johnson"). A prefix cannot show
which word comes next, so this program uses only a rough proxy: names and titles (capitalised
words, most of all a capitalised word after another) are a little more negative than
lowercase words, and punctuation, digits and the like sit nearest zero.
"""

READS: tuple[str, ...] = ()


def _word(s):
    return s.strip().isalpha()


def _capital(s):
    return s.strip()[:1].isupper()


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1]
    same_doc = len(prefix.document_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = prefix.token_strings[-2] if same_doc else ""
    if _capital(cur) and _capital(prev):
        return None, -0.22
    if _capital(cur):
        return None, -0.14
    if _word(cur):
        return None, -0.12
    return None, -0.07
